INSERT INTO message (message_id, conversation_id, role, content, token_count, user_ern, given_name, family_name, created_at) VALUES ('bfd1c522-2dcd-4095-875b-23e45c997d22', 'c91b73d1-cbc4-42f7-979a-57288d51a9aa', 'user', 'external partners, but some internal staff - we can focus just on external though as that will help everyone', NULL, 'ern:emis:user:user:7ae7b859-c480-4644-b3be-d77d628f6e7e', 'Luke', 'Smith', '2026-05-31 18:41:35.192183+00');
INSERT INTO message (message_id, conversation_id, role, content, token_count, user_ern, given_name, family_name, created_at) VALUES ('09cd95e5-2403-4e79-82c5-66b4a0e2a93f', 'c91b73d1-cbc4-42f7-979a-57288d51a9aa', 'assistant', 'Got it — external partner developers are the primary users, with the understanding that solving for them benefits internal staff too.
