INSERT INTO message (message_id, conversation_id, role, content, token_count, user_ern, given_name, family_name, created_at) VALUES ('43df59cc-332e-4dfa-bd09-533bf91917f4', 'c91b73d1-cbc4-42f7-979a-57288d51a9aa', 'assistant', '10 seconds is the threshold — I''ll set p95 < 10s as the SLO.
Let me now confirm Requirement 1 before we save it:
---
**Requirement 1: Conversational Q&A Chat Widget**
**Acceptance Criteria:**
- ✓ Widget appears in bottom-right corner on every portal page
- ✓ Bot answers questions by reformulating doc content in clearer language with examples
- ✓ Every answer includes a citation: page URL + relevant quoted lines from source
- ✓ Out-of-scope questions (e.g. "what''s the weather?") receive a polite deflection: *"I can only help with questions about EMIS interoperability — please try asking about our APIs or authentication flows."*
- ✓ Conversation persists across page navigation until browser close or explicit "Clear conversation" button press
**Evaluation Criteria (Deterministic):**
- ✓ REJECT: "What''s the weather like today?" → polite out-of-scope deflection, no doc citation
- ✓ ACCEPT: "Which auth flow should I use for a backend API?" → answer with reformulated explanation + example + citation (URL + quoted lines)
- ✓ MUST RETURN: answer text, citation URL, quoted source lines
- ✓ TIMING: p95 response < 10s
**Clinical Safety:** N/A (not safety-critical)
**Information Governance:** No patient data; email address captured on escalation (GDPR Article 6 lawful basis TBD)
**Security:** No auth required to use widget; HTTPS/TLS in transit
**Observability:** Response success rate, p95 latency, out-of-scope deflection rate
**Frontend:** Floating widget (bottom-right), full-page mode, @emisgroup/ui-* components, i18n, jest-axe
**Priority:** Must Have | **Effort:** High | **Risk:** High
Is this correct?', NULL, NULL, NULL, NULL, '2026-05-31 18:52:27.882064+00');
