INSERT INTO message (message_id, conversation_id, role, content, token_count, user_ern, given_name, family_name, created_at) VALUES ('80f6de9c-a5a5-4286-aa0a-c4d44a3c7fe6', '71a9af59-f14c-4ed0-842c-7c6aa74c8b3f', 'assistant', 'Great — full coverage it is. Now let me ask about visual direction.
**Phase 2: Visual Direction**
Any visual preferences for the prototype?
- **A — Clean and minimal** — system fonts, simple cards, blue primary (`#2563eb`)
- **B — Healthcare professional** — clinical-feeling UI with clear hierarchy (not applicable here, but available)
- **C — Match an existing product** — the bot lives inside an **Astro/Starlight documentation portal**, so I can style it to feel like a docs-site chat widget (dark sidebar, light content area, monospace accents)
- **D — No preference** — I''ll use a clean default that fits a developer documentation context
Also: do you have any wireframes or sketches to guide layouts? If not, I''ll derive everything from the requirements.', NULL, NULL, NULL, NULL, '2026-05-31 19:49:37.301735+00');
INSERT INTO message (message_id, conversation_id, role, content, token_count, user_ern, given_name, family_name, created_at) VALUES ('1ca3f672-765c-4d81-bf94-01c886d47112', '71a9af59-f14c-4ed0-842c-7c6aa74c8b3f', 'user', 'C - just the astro/starlight default', NULL, 'ern:emis:user:user:7ae7b859-c480-4644-b3be-d77d628f6e7e', 'Luke', 'Smith', '2026-05-31 19:49:58.112451+00');
INSERT INTO message (message_id, conversation_id, role, content, token_count, user_ern, given_name, family_name, created_at) VALUES ('aaa7ffba-6b59-41c6-9bca-ea94dda4c2fc', '71a9af59-f14c-4ed0-842c-7c6aa74c8b3f', 'assistant', 'Perfect. I''ll style it to match the Astro/Starlight default theme — dark sidebar, clean white content area, purple/indigo accent (`#7c3aed` / Starlight''s signature violet), monospace code hints, and the characteristic docs-site layout feel.
Let me now load all the requirement files to build the full screen plan.
All requirements loaded. Here''s the **build plan** — please approve and I''ll generate the full prototype.
---
## Prototype Build Plan
**Theme:** Astro/Starlight default — dark sidebar (`#1e1e2e`), white content area, violet accent (`#7c3aed`), monospace font hints
---
### Screens & States
| # | Screen / State | Covers |
|---|---|---|
| 1 | **Portal page (docs view)** | Base Starlight layout — dark sidebar, breadcrumbs, content. Widget visible bottom-right. |
| 2 | **Widget — idle / closed** | Floating button with unread indicator. |
| 3 | **Widget — open, empty** | Welcome message, input field. REQ-001 |
| 4 | **Widget — loading** | Spinner + sequential tool call status messages ("Searching documentation…", "Retrieving examples…"). REQ-006 |
| 5 | **Widget — answer with citation** | Bot reply, source URL, quoted lines. REQ-001 |
| 6 | **Widget — out-of-scope deflection** | Polite deflection message, no citation. REQ-001 |
| 7 | **Widget — escalation prompt** | "I couldn''t find an answer — would you like to escalate?" + email form. REQ-002 |
| 8 | **Widget — escalation email validation** | Invalid email inline error. REQ-002 |
| 9 | **Widget — escalation success** | Confirmation message, form hidden. REQ-002 |
| 10 | **Widget — timeout error** | "Sorry, that''s taking longer than expected…" with escalation link. REQ-006 |
| 11 | **Widget — clear conversation dialog** | Confirmation modal before clearing. REQ-005 |
| 12 | **Full-page `/chat` view** | Same conversation, expand/minimise control, shared history. REQ-003 |
| 13 | **Unauthenticated state** | Widget not rendered; redirect notice shown. REQ-001/REQ-003 |
---
### Navigation Flow
```
Portal page (authenticated)
  └── Widget button (bottom-right)
        └── Widget open → [ask question] → Loading → Answer / Deflection / Timeout
                                         → [escalate] → Email form → Validation → Success
                                         → [clear] → Confirmation dialog → Empty state
                                         → [expand ↗] → Full-page /chat view
                                                           → [← back] → Widget
Portal page (unauthenticated)
  └── Login redirect notice shown; widget absent
```
---
### Hardcoded Demo Scenarios
- **Scenario A (in-scope):** "Which auth flow should I use for a backend API?" → full answer + citation
- **Scenario B (out-of-scope):** "What''s the weather like today?" → deflection
- **Scenario C (escalation):** "How do I handle token refresh for SMART on FHIR?" → bot can''t answer → escalation form
- **Scenario D (timeout):** Triggered via a "Simulate timeout" button in the demo toolbar
---
Shall I proceed? Reply **"go"** (or any approval) and I''ll build the full file.', NULL, NULL, NULL, NULL, '2026-05-31 19:50:22.98044+00');
