INSERT INTO artefact (artefact_id, project_id, version, file_path, content_type, content, size_bytes, created_by, created_at) VALUES ('e1607276-345b-4386-a5b0-43a7c63444b1', '03735ad1-8759-414e-a93f-ce8cc7bfc1fc', 1, 'prototype/index.html', 'text/markdown', E'<!DOCTYPE html>
