}
.citation-card .citation-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--sl-accent);
  margin-bottom: 4px;
}
.citation-card .citation-url {
  color: var(--sl-accent);
  font-family: monospace;
  font-size: 11px;
  word-break: break-all;
  display: block;
  margin-bottom: 4px;
}
.citation-card .citation-quote {
  color: #4c1d95;
  font-style: italic;
  font-size: 12px;
  border-left: 2px solid var(--sl-accent-light);
  padding-left: 8px;
}
/* Loading / status */
.loading-state {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.loading-bubble {
  background: white;
  border: 1px solid var(--sl-content-border);
  border-radius: 12px;
  border-top-left-radius: 2px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
  color: var(--sl-content-muted);
  min-width: 160px;
}
.loading-dots {
  display: flex; gap: 4px; align-items: center;
}
.loading-dot {
  width: 7px; height: 7px;
  background: var(--sl-accent-light);
  border-radius: 50%;
  animation: dot-pulse 1.2s infinite ease-in-out;
}
.loading-dot:nth-child(2) { animation-delay: 0.2s; }
.loading-dot:nth-child(3) { animation-delay: 0.4s; }
@keyframes dot-pulse {
  0%, 80%, 100% { opacity: 0.3; transform: scale(0.85); }
  40% { opacity: 1; transform: scale(1); }
}
.status-text {
  font-size: 12px;
  color: var(--sl-content-muted);
  display: flex;
  align-items: center;
  gap: 5px;
}
.status-spinner {
  width: 12px; height: 12px;
  border: 2px solid #e0e7ff;
  border-top-color: var(--sl-accent);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  flex-shrink: 0;
}
@keyframes spin { to { transform: rotate(360deg); } }
/* Welcome message */
.welcome-msg {
  text-align: center;
  padding: 20px 16px;
  color: var(--sl-content-muted);
}
.welcome-msg .welcome-icon { font-size: 32px; margin-bottom: 8px; }
.welcome-msg h4 { font-size: 14px; font-weight: 700; color: var(--sl-content-text); margin-bottom: 4px; }
.welcome-msg p { font-size: 12.5px; }
.welcome-suggestions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
}
.suggestion-chip {
  background: white;
  border: 1px solid rgba(124,58,237,0.25);
  border-radius: 20px;
  padding: 6px 12px;
  font-size: 12px;
  color: var(--sl-accent);
  cursor: pointer;
  text-align: left;
  transition: background 0.1s, border-color 0.1s;
}
.suggestion-chip:hover { background: var(--sl-accent-bg); border-color: var(--sl-accent); }
/* Error / timeout */
.error-bubble {
  background: var(--sl-error-bg);
  border: 1px solid #fca5a5;
  border-radius: 12px;
  border-top-left-radius: 2px;
  padding: 10px 12px;
  font-size: 13px;
  color: var(--sl-danger);
}
.error-bubble .error-actions {
  margin-top: 8px;
  display: flex;
  gap: 8px;
}
.error-link {
  font-size: 12px;
  color: var(--sl-accent);
  cursor: pointer;
  text-decoration: underline;
  background: none;
  border: none;
  padding: 0;
}
/* Deflection bubble */
.deflection-bubble {
  background: var(--sl-warning-bg);
  border: 1px solid #fcd34d;
  border-radius: 12px;
  border-top-left-radius: 2px;
  padding: 10px 12px;
  font-size: 13px;
  color: #92400e;
}
/* Escalation form */
.escalation-form {
  margin-top: 10px;
  background: white;
  border: 1px solid var(--sl-content-border);
  border-radius: var(--radius);
  padding: 12px;
}
.escalation-form .esc-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--sl-content-text);
  margin-bottom: 8px;
}
.escalation-form .esc-desc {
  font-size: 12px;
  color: var(--sl-content-muted);
  margin-bottom: 10px;
}
.form-field { margin-bottom: 8px; }
.form-label {
  display: block;
  font-size: 12px;
  font-weight: 500;
  color: var(--sl-content-text);
  margin-bottom: 4px;
}
.form-input {
  width: 100%;
  border: 1px solid var(--sl-content-border);
  border-radius: var(--radius-sm);
  padding: 7px 10px;
  font-size: 13px;
  color: var(--sl-content-text);
  outline: none;
  transition: border-color 0.15s;
  background: white;
}
.form-input:focus { border-color: var(--sl-accent); box-shadow: 0 0 0 2px rgba(124,58,237,0.12); }
.form-input.error { border-color: var(--sl-danger); }
.form-error {
  font-size: 11px;
  color: var(--sl-danger);
  margin-top: 3px;
  display: none;
}
.form-error.visible { display: block; }
.esc-submit {
  width: 100%;
  background: var(--sl-accent);
  color: white;
  border: none;
  border-radius: var(--radius-sm);
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
  margin-top: 4px;
}
.esc-submit:hover { background: var(--sl-accent-hover); }
.esc-submit:disabled { background: #a78bfa; cursor: not-allowed; }
/* Escalation success */
.escalation-success {
  background: var(--sl-success-bg);
  border: 1px solid #86efac;
  border-radius: var(--radius);
  padding: 12px;
  font-size: 13px;
  color: #14532d;
  display: flex;
  gap: 8px;
  align-items: flex-start;
}
.escalation-success .success-icon { font-size: 16px; flex-shrink: 0; }
/* Widget input area */
.widget-input-area {
  padding: 10px 12px;
  border-top: 1px solid var(--sl-content-border);
  background: white;
  flex-shrink: 0;
}
.widget-input-row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}
.widget-input {
  flex: 1;
  border: 1px solid var(--sl-content-border);
  border-radius: 20px;
  padding: 8px 14px;
  font-size: 13.5px;
  outline: none;
  resize: none;
  max-height: 80px;
  min-height: 36px;
  line-height: 1.4;
  transition: border-color 0.15s;
  background: #f8fafc;
  color: var(--sl-content-text);
  font-family: inherit;
}
.widget-input:focus { border-color: var(--sl-accent); background: white; }
.widget-input::placeholder { color: #9ca3af; }
.widget-send-btn {
  width: 36px; height: 36px;
  background: var(--sl-accent);
  border: none;
  border-radius: 50%;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: white;
  font-size: 15px;
  transition: background 0.15s, transform 0.1s;
  flex-shrink: 0;
}
.widget-send-btn:hover { background: var(--sl-accent-hover); transform: scale(1.05); }
.widget-send-btn:disabled { background: #c4b5fd; cursor: not-allowed; transform: none; }
.widget-input-footer {
  font-size: 10px;
  color: #9ca3af;
  text-align: center;
  margin-top: 5px;
}
/* Rate limit notice */
.rate-limit-notice {
  font-size: 11px;
  color: var(--sl-warning);
  text-align: center;
  padding: 4px;
}
/* ============================================================
   FULL-PAGE CHAT VIEW
   ============================================================ */
#view-fullpage {
  display: none;
  height: calc(100vh - 30px);
  flex-direction: column;
  background: white;
}
#view-fullpage.active { display: flex; }
.fullpage-header {
  background: var(--sl-accent);
  color: white;
  padding: 0 24px;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 16px;
  flex-shrink: 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.fullpage-back-btn {
  background: rgba(255,255,255,0.15);
  border: none;
  border-radius: var(--radius-sm);
  padding: 6px 12px;
  color: white;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  display: flex; align-items: center; gap: 6px;
  transition: background 0.1s;
}
.fullpage-back-btn:hover { background: rgba(255,255,255,0.25); }
.fullpage-title {
  flex: 1;
  font-size: 16px;
  font-weight: 700;
}
.fullpage-subtitle {
  font-size: 12px;
  opacity: 0.75;
}
.fullpage-clear-btn {
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  padding: 5px 12px;
  color: white;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.1s;
}
.fullpage-clear-btn:hover { background: rgba(255,255,255,0.2); }
.fullpage-body {
  display: flex;
