}
.fullpage-messages::-webkit-scrollbar { width: 6px; }
.fullpage-messages::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 3px; }
.fullpage-msg {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  max-width: 760px;
  margin: 0 auto;
  width: 100%;
}
.fullpage-msg.user { flex-direction: row-reverse; }
.fullpage-msg-avatar {
  width: 36px; height: 36px;
  border-radius: 50%;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  font-weight: 700;
}
.fullpage-msg.bot .fullpage-msg-avatar { background: var(--sl-accent); color: white; }
.fullpage-msg.user .fullpage-msg-avatar { background: #e0e7ff; color: var(--sl-accent); }
.fullpage-msg-content {
  max-width: 80%;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.fullpage-msg-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--sl-content-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.fullpage-msg.user .fullpage-msg-label { text-align: right; }
.fullpage-bubble {
  padding: 12px 16px;
  border-radius: 12px;
  font-size: 14px;
  line-height: 1.6;
}
.fullpage-msg.bot .fullpage-bubble {
  background: white;
  border: 1px solid var(--sl-content-border);
  border-top-left-radius: 2px;
  color: var(--sl-content-text);
}
.fullpage-msg.user .fullpage-bubble {
  background: var(--sl-accent);
  color: white;
  border-top-right-radius: 2px;
}
.fullpage-input-area {
  background: white;
  border-top: 1px solid var(--sl-content-border);
  padding: 16px 24px;
  flex-shrink: 0;
}
.fullpage-input-inner {
  max-width: 760px;
  margin: 0 auto;
}
.fullpage-input-row {
  display: flex;
  gap: 12px;
  align-items: flex-end;
}
.fullpage-input {
  flex: 1;
  border: 1px solid var(--sl-content-border);
  border-radius: var(--radius);
  padding: 10px 16px;
  font-size: 14px;
  outline: none;
  resize: none;
  max-height: 120px;
  min-height: 44px;
  line-height: 1.5;
  transition: border-color 0.15s;
  background: #f8fafc;
  color: var(--sl-content-text);
  font-family: inherit;
}
.fullpage-input:focus { border-color: var(--sl-accent); background: white; }
.fullpage-input::placeholder { color: #9ca3af; }
.fullpage-send-btn {
  background: var(--sl-accent);
  border: none;
  border-radius: var(--radius);
  padding: 10px 20px;
  color: white;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
  display: flex; align-items: center; gap: 6px;
  height: 44px;
  flex-shrink: 0;
}
.fullpage-send-btn:hover { background: var(--sl-accent-hover); }
.fullpage-input-footer {
  font-size: 11px;
  color: #9ca3af;
  margin-top: 8px;
  text-align: center;
}
/* Fullpage sidebar (session info) */
.fullpage-sidebar {
  width: 240px;
  border-left: 1px solid var(--sl-content-border);
  background: white;
  padding: 20px 16px;
  overflow-y: auto;
  flex-shrink: 0;
}
.fp-sidebar-section { margin-bottom: 20px; }
.fp-sidebar-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--sl-content-muted);
  margin-bottom: 8px;
}
.fp-sidebar-item {
  font-size: 12.5px;
  color: var(--sl-content-text);
  padding: 4px 0;
  border-bottom: 1px solid #f1f5f9;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.fp-sidebar-item .fp-val {
  font-weight: 500;
  color: var(--sl-accent);
  font-size: 12px;
}
.session-badge {
  display: inline-block;
  background: var(--sl-accent-bg);
  color: var(--sl-accent);
  border-radius: 10px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
}
/* ============================================================
   MODAL / DIALOG
   ============================================================ */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 8500;
  display: none;
  align-items: center;
  justify-content: center;
}
.modal-backdrop.open { display: flex; }
.modal {
  background: white;
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  padding: 24px;
  max-width: 400px;
  width: 90%;
  animation: modal-appear 0.15s ease-out;
}
@keyframes modal-appear {
  from { opacity: 0; transform: scale(0.95); }
  to   { opacity: 1; transform: scale(1); }
}
.modal h3 { font-size: 17px; font-weight: 700; margin-bottom: 8px; }
.modal p { font-size: 14px; color: var(--sl-content-muted); margin-bottom: 20px; }
.modal-actions { display: flex; gap: 10px; justify-content: flex-end; }
/* ============================================================
   UTILITY CLASSES
   ============================================================ */
.hidden { display: none !important; }
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}
.tag {
  display: inline-block;
  background: var(--sl-accent-bg);
  color: var(--sl-accent);
  border-radius: 10px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
  margin-right: 4px;
}
/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 768px) {
  .portal-shell {
    grid-template-columns: 1fr;
    grid-template-rows: 48px 1fr;
  }
  .sl-sidebar { display: none; }
  .widget-panel { width: calc(100vw - 32px); right: 16px; }
  .fullpage-sidebar { display: none; }
  .content-inner { padding: 24px 20px 80px; }
}
</style>
</head>
