<div id="view-fullpage">
  <div id="proto-banner-fp" style="background:#fbbf24;color:#1c1917;text-align:center;font-size:12px;font-weight:600;padding:5px 12px;font-family:system-ui;letter-spacing:0.01em;">
    ⚠️ PROTOTYPE ONLY — Requirements validation artefact (QABOT-001). Not for production use.
  </div>
  <div class="fullpage-header">
