<!-- ============================================================
     PORTAL SHELL (normal docs view)
     ============================================================ -->
<div class="portal-shell" id="portal-shell">
  <!-- HEADER -->
  <header class="sl-header">
    <a class="logo" href="#" onclick="navigateTo(''home'');return false;">
